import * as React from "react";
import { MpaIcon } from "../icon/MpaIcon";
import "./Switch.scss";

export interface SwitchProps {
  /**
   * Unique identifier for the switch component
   */
  id: string;
  /**
  * Identifying name for the switch 
  */
  name?: string;
   /**
   * Determines whether this switch is checked.
   */
  value?: string;  
  /**
   * Determines whether this switch is checked.
   */
  checked?: boolean; 
  /**
   * Hex code that determines the background colour of the field when it is checked.
   */
  colour?: "primary" | "secondary" | "tertiary";
   /**
   * Custom onChange function that can be defined for the switch.
   */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /**
   * Boolean that determines if the switch can be interacted with.
   */
  disabled?: boolean;
  /**
   * Text to be displayed below the input field in case of an error.
   */
  errorText?: string;
  /**
   * Custom classNames that can be provided for style extension / overrides.
   */
  className?: string;
  /**
   * The string to be displayed beside the switch.
  */
  label?: string;
}

const Switch: React.FC<SwitchProps> = ({
  id,
  name,
  value,
  checked,
  colour= "primary",
  onChange,
  disabled,
  errorText="",
  className="",
  label="",
}) => {

  const switchClassName = `${colour} ${disabled ? "disabled" : ""}`;
  const disabledClassName = ` ${disabled ? "disabled" : ""}`;

  return (
    <>
    {/* <div className={`form-check form-switch ${switchClassName} ${className}`}> */}
      <div className={`switch-wrapper ${className}`}>
      <label className={`switch-container ${disabledClassName} `}>
          <div className="switch-item">
              <input    
                  type="checkbox" 
                  id={id}
                  name={name}   
                  // className={`switch-input ${switchClassName}`} 
                  className={`switch-input ${colour} `}
                  checked={checked}
                  value={value}
                  onChange={onChange} 
                  disabled={disabled}
                    
              />
              <span className={`custom-switch ${switchClassName}`} ></span>
              <div className={`switch-hover-shadow ${switchClassName}`}></div>
          </div>
          <div className={`switch-label ${switchClassName}`}>
              <span>{label}</span>
          </div>
      </label>
    </div>
    <div>
    {errorText?.trim() !== ""   && (
      <div>         
          <p className="error-text"><MpaIcon iconName="AlertCircle" colour="var(--mpa-red-80)"/>
          <span className="error-text-padding">
          {errorText}
          </span>
          </p>
      </div>
    )}
    </div>
    </>
    
  );
};

export default Switch;
